/* 2.0 创意发现与统一编辑；内容与规则由现有内容文件提供。 */
(function(){'use strict';
const DISCOVERY_ENABLED=false; // 保留创意发现实现，仅关闭前端入口与路由
const C=window.StudioCore,$=s=>document.querySelector(s),E=C.esc,root=$('#app');
const loaded=C.load(localStorage),db=loaded.data;let blocked=loaded.blocked;
const restrictedPurchase=text=>window.TMB_RULES.hasRestrictedPurchase?window.TMB_RULES.hasRestrictedPurchase(text):window.TMB_RULES.scan(text).some(x=>x.code==='device-purchase');
const ITEMS=(window.TMB_ITEMS||[]).filter(i=>!restrictedPurchase(JSON.stringify(i))),PLAT=window.TMB_PLATFORMS,STORES=sharedStores(),PB=window.TMB_PLAYBOOK,SLOTS=window.TMB_SLOTS;
function sharedStores(){const list=C.clone(window.TMB_STORES||[]);try{for(const saved of JSON.parse(localStorage.getItem('tmb.studio2.legacy.stores')||'[]')){const hit=list.find(x=>x.id===saved.id);if(hit){for(const [k,v]of Object.entries(saved.vars||{}))if(v)hit.vars[k]=v;}else if(saved.id!=='s1')list.push(saved);}}catch{}return list;}
function sharedStoreId(){try{return JSON.parse(localStorage.getItem('tmb.studio2.legacy.cur')||'null')}catch{return null;}}
function saveSharedStore(){try{localStorage.setItem('tmb.studio2.legacy.cur',JSON.stringify(state.storeId));}catch{notify('门店选择无法保存，跨页面同步未成功。');}}
function syncSharedStore(){const id=sharedStoreId();if(id&&id!==state.storeId&&STORES.some(s=>s.id===id)){state.storeId=id;db.settings.storeId=id;render();}}
const names={xhs:'小红书',pyq:'朋友圈',douyin:'抖音',sph:'视频号'};
const tips={douyin:'动作或问题开场，用真实镜头承接；分开设计封面与前 3 秒。',xhs:'封面聚焦一个理由，组图补充细节，正文提供可保存的实用信息。',sph:'把场景、流程与行动入口讲清楚，保留适合转发的说明。',pyq:'主图集中表达，配文简短自然；门店与活动条件清楚。'};
const state={view:'discover',platform:(()=>{try{return JSON.parse(localStorage.getItem('tmb.shared.platform')||localStorage.getItem('tmb.studio2.legacy.tab')||'null')}catch{return null}})()||db.settings.platform||'douyin',storeId:sharedStoreId()||db.settings.storeId||STORES[0].id,theme:'',angle:'',form:'',q:'',page:0,selected:null,library:'ideas',draft:null,dirty:false,frame:0,fieldTab:'assets',returnHash:'#discover',scroll:0};
if(!PLAT[state.platform])state.platform='douyin';if(!STORES.some(s=>s.id===state.storeId))state.storeId=STORES[0].id;
let lastFocus=null,toastTimer,headerObserver;const B=(label,a,v='',cl='')=>`<button type="button" class="${cl}" data-action="${a}" data-value="${E(v)}">${label}</button>`;
const link=(label,url,cl='button')=>`<a class="${cl}" href="${E(url)}">${label}</a>`;
const r=(s,d=state.draft)=>C.resolve(s,d?d.vars:store().vars);
function store(){return STORES.find(s=>s.id===state.storeId)||STORES[0];}
function notify(t){const el=$('#toast');el.textContent=t;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),6500);}
function persist(){if(blocked){notify(loaded.error);return false;}const res=C.save(localStorage,db);if(!res.ok)notify(res.error);return res.ok;}
function saveDraft(silent=false){if(!state.draft)return true;const before=C.clone(db.drafts);C.upsert(db,state.draft);if(!persist()){db.drafts=before;return false;}state.dirty=false;const s=$('#save-state');if(s)s.textContent='已保存到当前浏览器';if(!silent)notify('草稿已保存到“我的创作”，仅在当前浏览器可用。');return true;}
function guard(){return !state.dirty||saveDraft(true);}
function go(hash){if(!guard())return;location.hash=hash;}
function queryHash(view){const q=new URLSearchParams({p:state.platform});if(state.theme)q.set('theme',state.theme);if(state.angle)q.set('angle',state.angle);if(state.form)q.set('form',state.form);if(state.q)q.set('q',state.q);if(state.page)q.set('page',state.page);if(state.selected)q.set('selected',state.selected);return '#'+view+'?'+q;}
function remember(){history.replaceState(null,'',queryHash(state.view));}
function header(){const city=store().vars['城市'],cities=[...new Set(STORES.map(s=>s.vars['城市']))];return `<header class="top"><div class="topline"><a class="brand" href="materials.html"><span class="mark">U</span><b>脱毛吧引流素材台（GPT版） · 2.0</b><span class="ver">v2.8.4</span></a><div class="store-pick"><label for="studio-city">城市</label><select id="studio-city" data-context="city" aria-label="城市">${cities.map(c=>`<option value="${E(c)}" ${c===city?'selected':''}>${E(c)}（${STORES.filter(s=>s.vars['城市']===c).length}）</option>`).join('')}</select><span class="sep"></span><label for="studio-store">门店</label><select id="studio-store" data-context="storeId" aria-label="门店">${STORES.filter(s=>s.vars['城市']===city).map(s=>`<option value="${s.id}" ${s.id===state.storeId?'selected':''}>${E(s.vars['简称'])}</option>`).join('')}</select></div><div class="header-tools">${[['GPT 设置','gptSettings'],['拆对标','btnBreak'],['门店与价格','btnStore'],['门店图库','btnPhotos'],['备份 / 导入','btnBackup']].map(([t,id])=>`<a class="header-tool ${id==='btnBreak'?'accent':''}" href="materials.html?tool=${id}">${t}</a>`).join('')}</div></div><nav class="nav studio-nav" aria-label="主要页面">${link('创意素材台','materials.html','')}${link('我的创作','#drafts',state.view==='drafts'||state.view==='edit'?'active':'')}${link('资料库','#library',state.view==='library'?'active':'')}</nav></header>`;}

function context(){return `<div class="context"><div class="platforms" aria-label="发布平台">${Object.keys(names).map(p=>`${p==='douyin'?'<span class="platform-divider" aria-hidden="true">|</span>':''}<button type="button" data-action="platform" data-value="${p}" aria-pressed="${p===state.platform}" class="${p===state.platform?'active':''}"><i class="platform-icon ${p}" aria-hidden="true"></i>${names[p]}<span class="n" title="公共模板数量">${ITEMS.filter(i=>i.p===p).length}</span></button>`).join('')}<span class="platform-guidance">方向参考 &amp; 拍摄引导</span></div></div>`;}
function catalog(){return C.filter(ITEMS,{platform:state.platform,theme:state.theme,angle:state.angle,form:state.form,q:state.q});}
function discoveryList(){return window.StudioDiscovery.list(ITEMS,state.platform,casesList(state.platform,'').concat(db.cases));}
function discover(){
 const all=discoveryList(),themes=[...new Set(all.map(v=>v.type))];
 const list=all.filter(v=>(!state.theme||v.type===state.theme)&&(!state.q||[v.title,v.description,...v.points].join(' ').includes(state.q))),chosen=list.find(v=>v.id===state.selected);
 return `${context()}<section class="intro"><h1>同一个主题，还能从哪些视角表达？</h1><p>选择主题 → 浏览表达视角 → 选择创意点 → 编辑字幕与分镜 → 生成创意结构</p><small>本地策划建议 · 每主题至少5个视角，每视角3个创意点 · 效果待验证</small></section><div class="themes">${B('全部主题','theme','',!state.theme?'active':'')}${themes.map(t=>B(E(t),'theme',t,t===state.theme?'active':'')).join('')}</div><form id="filter-form" class="filters"><input name="q" type="search" aria-label="搜索创意" placeholder="搜索视角或创意点" value="${E(state.q)}"><button type="submit">搜索</button>${B('重置','reset')}<small>${list.length} 个视角 · ${list.length*3} 个创意点</small></form><p class="note">${E(all[0]?.lead||'')}</p><div class="discovery section"><section class="view-list">${list.length?list.map(v=>`<button class="view-card ${chosen?.id===v.id?'selected':''}" data-action="select" data-value="${v.id}" aria-pressed="${chosen?.id===v.id}"><small>${E(v.type)} · ${v.derived?'案例提炼 · 待核实':'策划视角'}</small><h2>${E(v.title)}</h2><p>${E(v.description)}</p><ol>${v.points.map(x=>`<li>${E(x)}</li>`).join('')}</ol><span>选择这个视角 →</span></button>`).join(''):'<div class="empty">没有匹配的视角，请调整搜索或重置。</div>'}</section><aside class="detail"><small>下一步 · 选择创意点</small>${chosen?`<h2>${E(chosen.title)}</h2>${chosen.source?`<p class="note">来源：${E(chosen.source.name)} ${C.safeURL(chosen.source.url)?`<a target="_blank" rel="noopener noreferrer" href="${E(C.safeURL(chosen.source.url))}">查看原案例</a>`:''} · 方法借鉴，效果待核实</p>`:''}<p>${E(chosen.description)}</p><p class="muted space">选择一个创意点进入编辑，可修改文字、配图说明与分镜。</p>${chosen.points.map((x,n)=>B(E(x)+' → 编辑','view-create',chosen.id+'|'+n,'full space')).join('')}`:'<h2>先选择左侧的表达视角</h2><p>视角决定从哪里讲，创意点决定怎样讲得更有新意。选定后再补充内容。</p>'}<p class="muted space">素材待匹配 · 飞书与在线AI未连接 · 不生成图片</p></aside></div>`;
}
function structureHTML(d){return `<div class="structure-map"><h3>完整创意结构</h3><p>${E(d.type)} → ${E(d.angle||d.title)}</p><p>${E(d.formula||'自主创意')}</p><div class="structure-flow">${d.frames.map((f,n)=>`<article><small>${n+1} · ${E(f.role)}</small><h3>${E(r(f.main))}</h3><p>${E(r(f.note))}</p><small>${db.assets.some(a=>a.id===f.assetId)?'已匹配本地素材':'素材待补充'}</small></article>`).join('')}</div><h3>发布文案与分镜</h3><pre style="white-space:pre-wrap">${E(Object.entries(d.f).map(([k,v])=>(C.labels[k]||k)+'：'+r(Array.isArray(v)?v.map(row=>Array.isArray(row)?row.join(' | '):row).join('\n'):v)).join('\n\n'))}</pre>${d.p==='pyq'?'<small>朋友圈正文 · 配图说明与首评分别编辑</small>':''}</div>`;}

function detail(i){const slots=[...new Set((i.frames||[]).map(f=>SLOTS[f.slot]?.name).filter(Boolean))];return `<aside class="detail" aria-label="创意详情"><small>创意详情 · ${E(i.id)}</small><h2>${E(r(i.title,null))}</h2><dl><dt>创意结构</dt><dd>${E(i.formula||i.angle||'从具体场景组织内容')}</dd><dt>适合怎样表达</dt><dd>${E(i.angle||'按内容与真实素材调整')}</dd><dt>${names[i.p]} · 平台适配</dt><dd>${tips[i.p]}</dd><dt>所需素材</dt><dd>${E(slots.join(' / ')||'按画面说明准备真实素材')}</dd><dt>内容完整度</dt><dd>${Object.keys(i.f||{}).length} 项文案 · ${(i.frames||[]).length} 张画面说明</dd></dl>${B('使用此创意，进入编辑','create',i.id,'primary')}${B('查看案例与创意依据','evidence',i.id,'full')}${link('查看完整模板','materials.html#'+encodeURIComponent(i.id),'button full')}<p class="muted space">参考图片与生图待素材库接入。现有模板中的活动、价格和体验表述需核实后使用。</p></aside>`;}
function begin(item){if(!guard())return;state.returnHash=location.hash.startsWith('#edit')?'#discover':location.hash;state.scroll=window.scrollY;state.draft=C.createDraft(item,store());state.referenceTheme=item.p==='xhs'?item.type:'';if(item.id?.startsWith('view-')||item.id?.startsWith('derived-'))state.draft.sourceId=null;if(item.discoverySource)state.draft.references.push({...item.discoverySource});state.draft.returnHash=state.returnHash;state.draft.returnScroll=state.scroll;state.frame=0;state.dirty=true;if(!saveDraft(true))return;go('#edit/'+state.draft.id);}
function fieldsHTML(d){return Object.entries(d.f).map(([key,val])=>`<label>${E(C.labels[key]||key)}${Array.isArray(val)?`<div class="table-wrap"><table><thead><tr><th>时长 / 顺序</th><th>画面</th><th>口播 / 字幕</th></tr></thead><tbody>${val.map((row,n)=>`<tr>${(Array.isArray(row)?row:[row]).map((s,m)=>`<td><textarea data-script="${key}" data-row="${n}" data-col="${m}" aria-label="第${n+1}段 ${['时长','画面','字幕'][m]||'内容'}">${E(s)}</textarea></td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<textarea data-copy="${E(key)}" rows="${String(val).length>180?7:3}">${E(val)}</textarea>`}</label>`).join('');}
function poster(d,f){const asset=db.assets.find(a=>a.id===f.assetId),pos=d.textPosition==='bottom'?'top:auto;bottom:18%':d.textPosition==='middle'?'top:38%':'top:8%';return `<div class="poster" id="poster" style="aspect-ratio:${d.ratio.replace(':','/')};background:${E(d.background)};color:${E(d.textColor)};font-family:${E(fontFamily(d))}">${asset?`<img src="${asset.data}" alt="${E(asset.name)}">`:`<div class="placeholder">真实素材待选择<br>当前仅为文字版式</div>`}<div class="type" style="${pos};font-size:${9*d.textScale}cqw"><span id="live-main">${E(r(f.main))}</span><div class="subtitle" id="live-sub">${E(r(f.sub))}</div></div><div class="store" id="live-store">${E(d.storeName)}</div></div>`;}
function editor(){const d=state.draft;if(!d)return `<div class="empty"><h2>没有找到这份草稿</h2><p>草稿保存在创建它的浏览器中。</p>${link('返回我的创作','#drafts')}</div>`;state.frame=Math.min(state.frame,d.frames.length-1);const f=d.frames[state.frame];return `<div class="crumb">${B('← 返回继续浏览','back','','quiet')}　${E(d.type)} / ${names[d.p]}</div><div class="editor-head"><div><label><span class="muted">作品名称</span><input data-draft="title" aria-label="作品名称" value="${E(d.title)}"></label><small id="save-state">${state.dirty?'有未保存修改':'已保存到当前浏览器'}</small></div><div class="row">${B('保存草稿','save')}${B('生成创意结构图','structure')}${B('发布与导出','preview','','primary')}</div></div><div class="editor"><aside class="panel structure"><h3>内容结构</h3><div class="frames">${d.frames.map((f,n)=>`<button type="button" data-action="frame" data-value="${n}" class="frame-button ${n===state.frame?'active':''}" aria-pressed="${n===state.frame}"><span>${String(n+1).padStart(2,'0')}　${E(f.role||'画面')}</span><small>${E(r(f.main))}</small></button>`).join('')}</div><div class="row space">${B('＋ 加一页','addframe')}${B('移除本页','removeframe','','quiet')}</div><details><summary>创意与来源</summary><p class="muted space">${E(d.formula||d.angle||'自主创意')}</p><p class="muted space">来源：${E(d.sourceTitle||'空白创意')}</p>${d.sourceId?link('查看完整模板','materials.html#'+encodeURIComponent(d.sourceId),'button full space'):''}</details>${d.execution?window.TMB_SERVICE.executionHTML(d.execution):''}${resultsHTML(d)}<details><summary>选题简报</summary>${Object.entries(d.brief||{}).map(([k,v])=>`<p class="muted space">${E({who:'面向谁',hook:'开头',msg:'核心信息',must:'必要信息',shoot:'拍摄建议',kpi:'观察指标'}[k]||k)}：${E(r(v))}</p>`).join('')}</details></aside><section class="panel"><div class="row between"><h3>画面与关键帧</h3><span class="pill">${names[d.p]} · ${d.ratio}</span></div><div class="canvas-wrap">${poster(d,f)}</div><p class="canvas-caption">${db.assets.find(a=>a.id===f.assetId)?.source==='小红书参考图'?'小红书参考图 · 来源已保留 · 可编辑文字层':db.assets.some(a=>a.id===f.assetId)?'当前浏览器的本地素材 · 可编辑文字层':'文字版式预览 · 尚未配置背景素材'}</p><div class="thumbs">${d.frames.map((_,n)=>B(String(n+1).padStart(2,'0'),'frame',n,n===state.frame?'active':'')).join('')}</div><div class="row space">${B('选择素材','resources','assets')}${B('导出当前图','png')}</div><details><summary>文字与构图（整套画面）</summary><div class="fields"><div class="two"><label>画面比例<select data-draft="ratio">${['9:16','3:4','1:1','16:9'].map(x=>`<option ${x===d.ratio?'selected':''}>${x}</option>`).join('')}</select></label><label>文字位置<select data-draft="textPosition">${[['top','上方'],['middle','居中'],['bottom','下方']].map(([v,l])=>`<option value="${v}" ${d.textPosition===v?'selected':''}>${l}</option>`).join('')}</select></label></div><label>字体<select data-draft="fontFamily">${["Microsoft YaHei","SimSun","sans-serif"].map(x=>`<option ${d.fontFamily===x?"selected":""}>${x}</option>`).join("")}</select></label><p class="muted">使用设备字体，跨设备可能不同。</p><label>文字大小<input type="range" min="0.6" max="1.4" step="0.05" value="${d.textScale}" data-draft="textScale"></label><div class="two"><label>文字颜色<input type="color" data-draft="textColor" value="${E(d.textColor)}"></label><label>底色<input type="color" data-draft="background" value="${E(d.background)}"></label></div>${f.assetId?B('移除当前背景','clearasset','','quiet'):''}</div></details><details><summary>画面生成 · 待接入</summary><p class="muted space">真实素材、参考案例、创意与平台规格共同参与生成。支持保留真实主体、局部改背景与多页统一风格；文字单独编辑。</p><button type="button" disabled class="full space">根据所选素材生成画面</button><p class="muted space">飞书与在线生图服务尚未连接；本版不会调用图片生成。</p></details></section><section class="panel edit-fields"><h3>当前画面 · ${state.frame+1} / ${d.frames.length}</h3><div class="fields space"><label>页名 / 片段<input data-frame-field="role" value="${E(f.role)}"></label><label>主标题<textarea data-frame-field="main" rows="2">${E(f.main)}</textarea></label><label>副标题<textarea data-frame-field="sub" rows="2">${E(f.sub)}</textarea></label><label>画面与字幕说明<textarea data-frame-field="note" rows="3">${E(f.note)}</textarea></label><label>门店名称<input data-draft="storeName" value="${E(d.storeName)}"></label></div><details><summary>构图、风格与素材要求</summary><div class="fields"><label>构图<textarea data-frame-field="layout" rows="3">${E(f.layout)}</textarea></label><label>风格<textarea data-frame-field="style" rows="2">${E(f.style)}</textarea></label><p class="muted">建议素材：${E(SLOTS[f.slot]?.name||'按当前创意选择')} ${E(SLOTS[f.slot]?.guide||'')}</p></div></details><details><summary>发布文案、分镜与评论话术 · ${Object.keys(d.f).length} 项</summary><div class="fields">${fieldsHTML(d)}</div></details><details><summary>门店、价格与活动变量</summary><p class="muted space">缺失值保持“待填”，请按当前业务事实填写。替换后同时影响预览与导出。</p><div class="fields space">${variables(d)}</div></details><div class="divider"><h3>内容与素材参考</h3><div class="row space">${B('素材','resources','assets')}${B('行业案例','resources','cases')}${B('创意','resources','ideas')}${B('合规','resources','rules')}</div><p class="muted space">${d.references.length?'已引用 '+d.references.length+' 条资料':'可从现有案例和创意结构中选择参考。'} · 飞书待接入</p></div><div id="checks" class="space">${checkHTML(d)}</div></section></div>`;}
function resultsHTML(d){const labels={likes:'点赞',comments:'评论',collects:'收藏',shares:'转发',visits:'可归因到店人数',redemptions:'新客核销人数',repeat:'再次到店人数',spend:'实际活动支出（元）'},v=d.results||{};return '<details><summary>发布后记录结果</summary><p class="muted space">手动记录，仅保存在当前浏览器。空白表示未获取，0表示已确认没有；外部点赞不能推算到店人数。</p><div class="fields"><label>观察周期<input data-result="period" value="'+E(v.period||'')+'" placeholder="例如：11月3日—11月10日"></label><label>归因依据<textarea data-result="attribution" placeholder="专属活动码、预约来源等；未知请注明">'+E(v.attribution||'')+'</textarea></label>'+Object.entries(labels).map(([k,l])=>'<label>'+l+'<input type="number" min="0" step="'+(k==='spend'?'0.01':'1')+'" data-result="'+k+'" value="'+E(v[k]??'')+'"></label>').join('')+'</div><p class="muted">保存草稿后保留记录，可随作品JSON导出；不自动认定活动成功。</p></details>';}
function variables(d){const tokens=[...new Set(JSON.stringify({f:d.f,frames:d.frames}).match(/\{[^{}\n]+\}/g)||[])].map(x=>x.slice(1,-1));return tokens.length?tokens.map(k=>`<label>${E(k)}<input data-var="${E(k)}" value="${E(d.vars[k]||'')}" placeholder="待填写已确认的信息"></label>`).join(''):'<p class="muted">当前内容没有待替换变量。</p>';}
function checkHTML(d){const c=C.scanDraft(d,window.TMB_RULES);return `<div class="note ${c.unresolved.length||c.hits.length?'warning':''}">${c.unresolved.length?'待填变量 '+c.unresolved.length+' 项。 ':''}${c.hits.length?'词表提示：'+c.hits.slice(0,8).map(x=>E(x.w)).join('、')+'。':'未命中当前关键词词表。'}<br>仍需核实活动、服务事实与平台规则；词表提示不等于完整合规结论。</div>`;}
function casesList(p=state.platform,theme=state.theme){const out=(window.TMB_SERVICE?.cases()||[]).map(c=>({...c,p,theme:c.goal,type:c.goal,verifiedService:true})),safe=c=>restrictedPurchase(JSON.stringify(c))?{id:c.id||c.name,name:'案例记录（摘要已过滤）',type:c.type||'行业案例',source:c.source||'已收录来源',url:c.url||'',what:'该条摘要已按素材台内容边界过滤。',why:'当前不纳入创意参考；补充经核实的服务信息与内容方法后再使用。',borrow:''}:c;for(const [cp,groups]of Object.entries(PB))for(const [t,pb]of Object.entries(groups||{}))(pb.cases||[]).forEach((c,n)=>out.push({...safe(c),id:'case-'+cp+'-'+Object.keys(groups).indexOf(t)+'-'+n,p,sourcePlatform:cp,theme:t}));(window.TMB_INDUSTRY_CASES||[]).forEach(c=>out.push({...safe(c),p,theme:'行业案例',official:true}));return out;}
function publicAssetHTML(editing){
 const p=editing?state.draft.p:state.platform;if(p!=='xhs')return '';
 const all=window.TMB_REFERENCE_ASSETS?.assets||[],themes=PLAT.xhs.themes.map(t=>t.name),chosen=state.referenceTheme||'';
 const list=all.filter(a=>!chosen||a.themes.includes(chosen));
 return `<section class="reference-library"><h3>小红书参考素材库</h3><p class="muted space">采集于2026-10-31 · ${all.length}张去重图片 · 保留作者与笔记来源 · 图片为原笔记参考，不代表本店实拍或已验证效果</p><div class="themes">${B('全部图片 '+all.length,'reference-theme','',!chosen?'active':'')}${themes.map(t=>B(E(t)+' '+all.filter(a=>a.themes.includes(t)).length+'张','reference-theme',t,chosen===t?'active':'')).join('')}</div><p class="note">按现有素材匹配主题；没有匹配图片时留空，后续配置。价格、活动和图片内文字按原笔记保留，使用前核实。人物与用户经历不能冒充本店顾客背书。飞书与在线AI尚未连接。</p><div class="assets section">${list.length?list.map(a=>`<article class="asset panel"><a href="${E(a.path)}" target="_blank" rel="noopener"><img src="${E(a.path)}" alt="${E(a.name)}" loading="lazy"></a><h3>${E(a.name)}</h3><small>${E(a.author)} · ${E(a.themes.join(' / '))}</small><p class="muted space">参考素材${a.caution?' · '+E(a.caution):''}</p><a href="${E(C.safeURL(a.sourceUrl))}" target="_blank" rel="noopener noreferrer">原笔记 ↗</a>${editing?B('加入创作参考','reference-bind',a.id,'full space')+B('用于当前画面（参考图）','reference-use',a.id,'full space'):''}</article>`).join(''):'<p class="empty">这个主题暂未配置匹配图片，可自行上传，或后续补充。</p>'}</div><p class="muted space">原笔记链接可能需要小红书登录；打不开时可按作者及标题搜索。下方为当前浏览器上传的自有素材。</p></section>`;
}

function resources(tab,editing=false){const p=editing?state.draft.p:state.platform,theme=editing?state.draft.type:state.theme;if(tab==='assets')return publicAssetHTML(editing)+`<div class="note">飞书共享云盘未连接。可以先上传真实图片到当前浏览器使用；不会上传到 GitHub 或云端。</div><div class="row section"><label class="upload">＋ 上传真实图片<input type="file" accept="image/jpeg,image/png,image/webp" id="asset-file"></label><small>支持 JPG / PNG / WebP，单张不超过 10MB</small></div><div class="assets section">${db.assets.length?db.assets.map(a=>`<article class="asset panel"><img src="${a.data}" alt="${E(a.name)}"><h3>${E(a.name)}</h3><small>${E(a.source==='小红书参考图'?'小红书参考图':'本地上传')} · ${new Date(a.createdAt).toLocaleDateString('zh-CN')}</small>${editing?B('用于当前画面','useasset',a.id,'full space'):''}</article>`).join(''):`<div class="empty"><p>还没有真实素材</p><small>门头、空间、设备和使用指引可按创作需要上传。</small></div>`}</div>`;
if(tab==='rules')return (window.TMB_XHS_POLICY?.html()||'')+`<h3>编辑时就能看到的合规提示</h3><p class="muted space">继承现有词表，规则来源与平台有效性需持续维护。这里不提供“审核通过”保证。</p>${editing?checkHTML(state.draft):''}<div class="case"><h3>效果与体验</h3><p>不虚构顾客体验和服务结果。涉及效果、适用范围和操作的内容，依据正式产品与服务说明核实。</p></div><div class="case"><h3>价格与活动</h3><p>填写已确认价格、条件和有效期，避免直接沿用过往模板中的活动信息。</p></div><div class="case"><h3>当前关键词词表</h3><p>${window.TMB_RULES.ban.map(E).join('、')}</p></div>`;
if(tab==='cases'){const list=casesList(p,theme),local=db.cases.filter(c=>c.p===p&&!restrictedPurchase(JSON.stringify(c))),all=local.concat(list);return `<section class="case-library">${window.TMB_SERVICE?.librarySummary()||''}<div class="row between"><h3>行业案例 · 对照表</h3>${B('录入行业案例','addcase')}</div><p class="note space">共 ${all.length} 条参考，包含已核验适配案例与历史行业资料。互动数据不等于到店效果；未获取的数据保持空缺标记，不补成 0。</p><div class="row section case-toolbar"><input type="search" data-case-search placeholder="搜索案例、行业、品牌或借鉴点" aria-label="搜索行业案例"><small data-case-count role="status">显示 ${all.length} 条</small><small class="muted">左右滑动查看全部维度 · 首列与表头固定</small></div><div class="case-table-scroll" tabindex="0" role="region" aria-label="行业案例对照表，可左右滚动"><table class="case-table"><caption>每行一个案例；按行业、账号、互动、内容与应用方法对照。</caption><colgroup><col style="width:210px"><col style="width:120px"><col style="width:160px"><col style="width:130px"><col style="width:230px"><col style="width:190px"><col style="width:250px"><col style="width:200px"></colgroup><thead><tr>${['案例','行业 / 目标','品牌 / 账号','互动数据','内容拆解','参考点','Ulike 脱毛吧可学习点','核验 / 依据'].map(t=>'<th scope="col">'+t+'</th>').join('')}</tr></thead><tbody>${all.map((c,n)=>caseHTML(c,editing,local.includes(c),n)).join('')}<tr data-case-empty ${all.length?'hidden':''}><td colspan="8">没有匹配案例，请调整搜索词。</td></tr></tbody></table></div></section>`;}

const pb=PB[p]?.[theme];const groups=pb?[[theme,pb]]:Object.entries(PB[p]||{});return `<h3>${names[p]} · 创意结构</h3><p class="muted space">保留现有主题公式、开头与图文方法。它们是参考方法，需要真实素材支撑。</p>${groups.map(([t,b])=>`<article class="case"><span class="pill">${E(t)}</span><h3 class="space">${E(b.content?.formula||b.summary||t)}</h3><p>${E(b.summary)}</p><details><summary>查看结构与拍摄建议</summary>${(b.content?.steps||[]).map(s=>`<p>${E(s.join(' · '))}</p>`).join('')}${(b.content?.tips||[]).map(s=>`<p class="muted">${E(s)}</p>`).join('')}</details>${editing?B('作为创意参考','bindidea',t,'space'):B('浏览这个主题','browsetheme',t,'space')}</article>`).join('')}`;}
function caseHTML(c,editing,custom=false,n=0){
 const url=C.safeURL(c.url),bound=state.draft?.references.some(x=>x.id===c.id),search=[c.name,c.type,c.source,c.what,c.mechanism,c.borrow,c.year,c.award,c.industry,c.brand,c.account,c.goal].join(' '),metric=v=>v===null||v===undefined||v===''?'<span class="case-missing">未获取</span>':E(v);
 return `<tr data-case-search-item data-case-search="${E(search)}"><th scope="row"><small class="case-number">${String(n+1).padStart(2,'0')}</small>${url?'<a href="'+E(url)+'" target="_blank" rel="noopener noreferrer">'+E(c.name)+' ↗</a>':E(c.name)}${c.year||c.award?'<small class="case-meta">'+E([c.year,c.award].filter(Boolean).join(' · '))+'</small>':''}</th><td><strong>${E(c.industry||'未记录行业')}</strong><span class="case-meta">${E(c.goal||c.type||'未分类')}</span></td><td><small class="case-label">品牌</small>${E(c.brand||'未记录')}<small class="case-label">账号</small>${E(c.account||'未记录')}<small class="case-meta">粉丝：${metric(c.fans)}</small></td><td><dl class="case-metrics">${[['点赞','likes'],['评论','comments'],['收藏','collects'],['转发','shares']].map(([l,k])=>'<dt>'+l+'</dt><dd>'+metric(c[k])+'</dd>').join('')}</dl></td><td>${E(c.what||'待补充内容拆解')}</td><td>${E(c.mechanism||'待补充独立方法拆解')}</td><td>${E(c.borrow||'待补充适配建议')}</td><td><span class="case-status">${E(c.verifiedService?'已核验 · '+c.evidence+'级':custom?'用户录入':c.official?'官方案例':'待复核')}</span><small class="case-meta">${E(c.source||'手动录入')}</small>${c.collectedAt?'<small class="case-meta">采集 '+E(c.collectedAt)+'</small>':''}<details><summary>依据与适用边界</summary><p>${E(c.limitations||c.why||'暂无已核验效果数据')}</p><p class="muted">只借鉴方法，不照搬原作者经历与未经确认的事实。</p></details>${editing?B(bound?'移除参考':'作为结构参考','bindcase',c.id,'space'):''}</td></tr>`;
}

function library(){return `<section class="intro"><h1>资料库</h1><p>在这里整理参考，也可以在编辑过程中直接调用。</p></section><div class="library-layout"><nav class="library-nav" aria-label="资料分类">${[['ideas','创意库'],['assets','素材库'],['cases','行业案例库'],['rules','合规库']].map(([k,n])=>B(n,'library',k,state.library===k?'active':'')).join('')}</nav><section class="panel">${resources(state.library)}</section></div>`;}
function drafts(){const list=db.drafts.filter(d=>d.p===state.platform&&d.storeId===state.storeId&&!!d.deletedAt===!!state.trash);return `<section class="draft-intro"><div class="draft-heading"><div><h1>${state.trash?"回收站":"我的创作"}</h1><p>草稿仅保存在当前浏览器，可导出后在其他设备导入继续编辑。</p></div><div class="draft-actions"><label class="upload">导入可编辑草稿<input id="draft-file" type="file" accept="application/json,.json"></label>${B("＋ 空白创意","blank","","primary")}</div></div><div class="draft-toolbar"><div class="draft-views">${B("我的作品","trash-view","",!state.trash?'active':'')}${B("回收站","trash-view","trash",state.trash?'active':'')}</div><span class="muted">${E(store().vars["简称"])} · ${names[state.platform]} · ${list.length} 份${state.trash?'已删除作品':'作品'}</span></div></section>${list.length?`<div class="drafts">${list.map(d=>`<article class="panel draft"><div class="row between"><span class="pill">${E(d.type||'空白创意')}</span><small>${names[d.p]}</small></div><h3>${E(C.resolve(d.title,d.vars))}</h3><p class="muted">${E(d.storeName)} · ${d.frames.length} 页 / 段</p><small>保存于 ${new Date(d.updatedAt).toLocaleString('zh-CN')}</small><div class="row">${d.deletedAt?B('恢复','restore',d.id)+B('彻底删除','purge',d.id):link('继续编辑','#edit/'+d.id,'button primary')+B('复制一份','duplicate',d.id)+B('移入回收站','trash',d.id)}</div></article>`).join('')}</div>`:`<div class="empty"><h2>${state.trash?"当前门店和平台的回收站为空":"当前门店和平台还没有草稿"}</h2><p>从模板或创意开始，保存后会出现在这里。</p>${link('浏览创意素材台','materials.html','button primary')} ${B('空白创意','blank')}</div>`}`;}
function render(){root.innerHTML=header()+`${state.view!=='edit'?`<div class="studio-context-sticky">${context()}</div>`:''}<main id="main" class="wrap">${state.view==='edit'?editor():state.view==='drafts'?drafts():state.view==='library'?library():discover()}</main><footer class="app-foot">本地编辑与保存 · 飞书未连接 · 在线生成未启用。价格、活动、体验与平台说明使用前请核实。</footer>`;headerObserver?.disconnect();const head=document.querySelector('.top');if(head&&typeof ResizeObserver!=='undefined'){headerObserver=new ResizeObserver(()=>document.documentElement.style.setProperty('--studio-header-height',head.getBoundingClientRect().height+'px'));headerObserver.observe(head);}syncCanvas();}
function modal(title,body){lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop"><section role="dialog" aria-modal="true" aria-labelledby="modal-title" class="modal"><header><h2 id="modal-title">${E(title)}</h2>${B('关闭','close')}</header>${body}</section></div>`;$('#overlay button')?.focus();}
function closeModal(){const o=$('#overlay');o.innerHTML='';if(lastFocus?.isConnected)lastFocus.focus();}
function showResources(tab){state.fieldTab=tab;modal('当前创作的参考',`<div class="resource-tabs">${[['assets','素材'],['cases','行业案例'],['ideas','创意'],['rules','合规']].map(([k,l])=>B(l,'resources',k,k===tab?'active':'')).join('')}</div><div class="resources">${resources(tab,true)}</div>`);}
function blank(){modal('从空白创意开始',`<form id="blank-form" class="fields"><label>这次想表达什么？<textarea name="idea" required maxlength="600" placeholder="例如：想让第一次来的人看懂扫码后的操作流程。"></textarea></label><div class="two"><label>发布平台<select name="p">${Object.entries(names).map(([p,n])=>`<option value="${p}" ${p===state.platform?'selected':''}>${n}</option>`).join('')}</select></label><label>内容主题<select name="theme">${[...new Set(ITEMS.map(i=>i.type))].map(t=>`<option>${E(t)}</option>`).join('')}</select></label></div><label>主要目标<select name="goal">${window.TMB_SERVICE.goals.map(g=>`<option>${E(g)}</option>`).join('')}</select></label><div class="two"><label>预算上限（元）<input name="budget" type="number" min="0" placeholder="未确定可留空"></label><label>赠礼<select name="gift"><option>不提供</option><option>允许</option></select></label></div><label>现场支持<select name="support"><option>无人现场支持</option><option>有人支持</option></select></label><label>已确认信息<textarea name="facts" placeholder="本店真实规则、可用素材和具体限制；未知项留空"></textarea></label><label>创建方式<select name="mode"><option value="blank">建立空白草稿，自行编写</option><option value="local">参考现有结构，生成本地初稿</option></select></label><p class="note">本地初稿依据内置规则和模板组织，不调用 GPT，不生成图片。使用前请核实事实并修改表达。</p><button class="primary" type="submit">开始创作</button></form>`);}
function preview(){const d=state.draft;if(!saveDraft(true))return;modal('发布与导出',`<p class="muted">当前作品：${E(d.title)} · ${names[d.p]} · ${d.frames.length} 页 / 段</p><div class="space">${checkHTML(d)}</div><section class="export-images"><h3>导出素材图</h3><p class="muted">按原画面顺序导出 PNG；可全选或只勾选需要的图片。</p><div class="row space">${B("全选","export-select","all")}${B("取消全选","export-select","none")}${B("导出勾选图片","export-images")}${B("导出全部图片","export-all")}</div><div class="export-grid">${d.frames.map((f,n)=>`<label class="export-frame"><input type="checkbox" data-export-frame="${n}" checked><span>${n+1}. ${E(f.role)}</span><img data-export-preview="${n}" alt="第${n+1}张图片预览"><small>${E(r(f.main))}</small></label>`).join("")}</div><p id="export-count">已选择 ${d.frames.length} 张</p></section><div class="row section">${B('复制发布文案','copy')}${B('下载文案 TXT','txt')}${B('下载发布包 ZIP','package')}${B('下载可编辑草稿','json')}</div><p class="muted space">发布包包含全部画面 PNG、文案与独立来源说明；缺少背景的画面导出文字版式。视频作品导出画面和脚本，不生成视频。朋友圈复制配文版本1。草稿文件用于跨设备继续编辑。未填写变量会按“待填”原样保留。</p><pre class="section">${E(publishText(d))}</pre><details><summary>来源与内部说明（不复制到发布文案）</summary><pre>${E(C.textExport(d))}</pre></details>`);loadExportPreviews();}
const previewWithContentGuard=preview;preview=function(){const d=state.draft,audit=C.scanDraft(d,window.TMB_RULES),hits=audit.hits.filter(x=>x.code==='device-purchase');if(hits.length){modal('先修改内容，再复制或导出',`<p>草稿里仍有不适用的仪器购买引导。请回到编辑页，检查标题、正文、分镜、评论/私信回复和配图文字后重试。</p>`);return;}previewWithContentGuard();};
async function loadExportPreviews(){const draft=state.draft;for(let n=0;n<draft.frames.length;n++){if(state.draft!==draft)return;const el=document.querySelector('[data-export-preview="'+n+'"]');if(!el)return;try{const blob=await png(true,n);if(!el.isConnected)return;const url=URL.createObjectURL(blob);el.onload=()=>URL.revokeObjectURL(url);el.src=url;}catch{el.alt='图片预览失败，请重试';}}}
function exportCount(){const inputs=[...document.querySelectorAll('[data-export-frame]')],count=inputs.filter(x=>x.checked).length;const el=document.querySelector('#export-count');if(el)el.textContent='已选择 '+count+' / '+inputs.length+' 张';return inputs.filter(x=>x.checked).map(x=>Number(x.dataset.exportFrame));}
function publishText(d){return (d.p==='pyq'?[d.f.v1?'v1':'post']:d.p==='xhs'?['title','body','tags']:['post','tags']).map(k=>C.resolve(d.f[k]||'',d.vars)).filter(Boolean).join('\n\n');}
function download(name,data,type){const a=document.createElement('a'),url=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type}));a.href=url;a.download=name.replace(/[<>:"/\\|?*]/g,'-');a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function fontFamily(d){return ["Microsoft YaHei","SimSun","sans-serif"].includes(d.fontFamily)?d.fontFamily:"Microsoft YaHei";}
async function png(asBlob=false,frameIndex=state.frame){const d=state.draft,f=d.frames[frameIndex],asset=db.assets.find(a=>a.id===f.assetId);const [a,b]=d.ratio.split(':').map(Number),w=1080,h=Math.round(w*b/a),canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');ctx.fillStyle=d.background;ctx.fillRect(0,0,w,h);if(asset){const image=new Image();image.src=asset.data;await image.decode();const scale=Math.max(w/image.width,h/image.height);ctx.drawImage(image,(w-image.width*scale)/2,(h-image.height*scale)/2,image.width*scale,image.height*scale);}ctx.fillStyle=d.textColor;const font=w*.09*d.textScale;ctx.font=`750 ${font}px "${fontFamily(d)}", sans-serif`;ctx.textBaseline='top';const lines=wrap(ctx,r(f.main),w*.84);let y=d.textPosition==='middle'?h*.38:d.textPosition==='bottom'?h*.82-lines.length*font*1.25:h*.08;lines.forEach(line=>{ctx.fillText(line,w*.08,y);y+=font*1.25;});ctx.font=`500 ${font*.45}px "${fontFamily(d)}", sans-serif`;y+=w*.035;wrap(ctx,r(f.sub),w*.84).forEach(line=>{ctx.fillText(line,w*.08,y);y+=font*.68;});ctx.font=`${w*.04}px "${fontFamily(d)}", sans-serif`;const sl=wrap(ctx,d.storeName,w*.84);sl.forEach((line,n)=>ctx.fillText(line,w*.08,h*.95-(sl.length-n)*w*.055));const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('图片导出失败');if(asBlob)return blob;download(d.title+'-'+(frameIndex+1)+'.png',blob,'image/png');notify('已下载当前画面 PNG');}

function wrap(ctx,text,max){const out=[];String(text).split('\n').forEach(p=>{let line='';for(const ch of p){if(line&&ctx.measureText(line+ch).width>max){out.push(line);line=ch;}else line+=ch;}out.push(line);});return out;}
async function upload(file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){notify('请选择不超过 10MB 的 JPG、PNG 或 WebP 图片。');return;}const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();const scale=Math.min(1,1600/Math.max(img.width,img.height)),cv=document.createElement('canvas');cv.width=Math.round(img.width*scale);cv.height=Math.round(img.height*scale);cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height);const a={id:C.uid(),name:file.name,data:cv.toDataURL('image/webp',.86),createdAt:new Date().toISOString(),source:'local'};db.assets.push(a);if(!persist()){db.assets.pop();return;}if(state.view==='edit')showResources('assets');else render();notify('图片已加入当前浏览器的素材库，没有上传到云端。');}catch(e){notify('无法读取这张图片，请尝试另一个文件。');}finally{URL.revokeObjectURL(url);}}
async function importDraft(file){if(!file)return;const original=C.clone(db);try{if(file.size>15*1024*1024)throw Error('文件过大');const pack=JSON.parse(await file.text());if(pack.format!=='tmb-studio2-draft'||pack.version!==1||!pack.draft||!Array.isArray(pack.draft.frames)||!pack.draft.frames.length||!names[pack.draft.p]||!pack.draft.f||!pack.draft.vars)throw Error('格式不正确');const d=pack.draft;delete d.deletedAt;if(!['9:16','3:4','1:1','16:9'].includes(d.ratio)||!/^#[0-9a-f]{6}$/i.test(d.textColor)||!/^#[0-9a-f]{6}$/i.test(d.background))throw Error('画面设置无效');d.textScale=Math.max(.6,Math.min(1.4,Number(d.textScale)||1));d.textPosition=['top','middle','bottom'].includes(d.textPosition)?d.textPosition:'top';d.references=Array.isArray(d.references)?d.references:[];const prior=C.clone(db),map={};for(const asset of pack.assets||[]){if(!/^data:image\/(png|jpeg|webp);base64,/.test(asset.data||''))throw Error('图片格式无效');const old=asset.id;asset.id=C.uid();map[old]=asset.id;db.assets.push(asset);}d.frames.forEach(f=>f.assetId=map[f.assetId]||null);d.id=C.uid();C.upsert(db,d);if(!persist()){Object.assign(db,prior);return;}render();notify('已导入为独立草稿，没有覆盖已有创作。');}catch(err){Object.assign(db,original);notify('无法导入：请使用本工具导出的有效草稿文件。');}}
function dirty(){state.dirty=true;const s=$('#save-state');if(s)s.textContent='有未保存修改';}
var previewSequence=0;async function syncCanvas(){if(state.view!=='edit'||!state.draft)return;const seq=++previewSequence;try{const blob=await png(true),el=$('#poster');if(seq!==previewSequence||!el)return;const url=URL.createObjectURL(blob),img=document.createElement('img');img.alt='当前作品画面预览';img.onload=()=>URL.revokeObjectURL(url);img.src=url;el.replaceChildren(img);}catch{}}
function updatePreview(){const d=state.draft;if(!d)return;const f=d.frames[state.frame],wrapEl=$('#poster')?.parentElement;if(wrapEl)wrapEl.innerHTML=poster(d,f);const check=$('#checks');if(check)check.innerHTML=checkHTML(d);syncCanvas();}
async function action(a,v){
if(['export-images','export-all','package','txt','copy','json','png'].includes(a)&&C.scanDraft(state.draft,window.TMB_RULES).hits.some(x=>x.code==='device-purchase')){notify('草稿含不适用内容，修改并通过检查后再复制或导出。');return;}
if(a==='export-select'){document.querySelectorAll('[data-export-frame]').forEach(x=>x.checked=v==='all');exportCount();return;}
if(a==='export-images'||a==='export-all'){const ids=a==='export-all'?state.draft.frames.map((_,n)=>n):exportCount();if(!ids.length){notify('请至少勾选一张图片');return;}notify('正在导出 '+ids.length+' 张图片…');const files=[];for(const n of ids)files.push({name:String(n+1).padStart(2,'0')+'.png',data:new Uint8Array(await (await png(true,n)).arrayBuffer())});download(state.draft.title+'-素材图.zip',window.StudioZip(files),'application/zip');notify('已导出 '+ids.length+' 张素材图，保留原画面序号。');return;}

if(a==='package'){if(!saveDraft(true))return;notify('正在打包图片与发布文案…');const files=[];for(let n=0;n<state.draft.frames.length;n++)files.push({name:String(n+1).padStart(2,'0')+'.png',data:new Uint8Array(await (await png(true,n)).arrayBuffer())});files.push({name:'发布文案.txt',data:new TextEncoder().encode(publishText(state.draft))},{name:'来源与说明.txt',data:new TextEncoder().encode(C.textExport(state.draft))});download(state.draft.title+'.zip',window.StudioZip(files),'application/zip');notify('已下载发布包：按顺序排列的图片、发布文案和独立来源说明。');return;}
if(a==='trash-view'){state.trash=!!v;render();return;}
if(['trash','restore','purge'].includes(a)){const d=db.drafts.find(x=>x.id===v);if(!d)return;if(a!=='restore'&&!confirm((a==='purge'?'彻底删除后无法恢复：':'移入回收站：')+d.title+'？'))return;const prior=C.clone(db.drafts);if(a==='purge')db.drafts=db.drafts.filter(x=>x.id!==v);else if(a==='restore')delete d.deletedAt;else d.deletedAt=new Date().toISOString();if(!persist()){db.drafts=prior;return;}if(state.draft?.id===v){state.draft=null;state.dirty=false;}render();notify(a==='restore'?'作品已恢复':a==='purge'?'作品已彻底删除':'作品已移入回收站');return;}

if(a==='reference-theme'){state.referenceTheme=v;if(state.view==='edit')showResources('assets');else render();return;}
if(a==='reference-bind'||a==='reference-use'){const ref=window.TMB_REFERENCE_ASSETS?.assets.find(x=>x.id===v);if(!ref||!state.draft)return;const id='xhs-reference-'+ref.id;if(a==='reference-bind'){if(!state.draft.references.some(x=>x.id===id))state.draft.references.push({id,name:ref.name,url:ref.sourceUrl,borrow:'参考图 · '+ref.author+' · '+ref.themes.join(' / ')});dirty();notify('已加入当前创作参考，可在内容与素材参考中查看来源。');return;}
try{let asset=db.assets.find(x=>x.id===id);if(!asset){const response=await fetch(ref.path);if(!response.ok)throw Error('图片未载入');const blob=await response.blob();if(!blob.type.startsWith('image/'))throw Error('图片格式错误');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});asset={...ref,id,data,source:'小红书参考图',createdAt:new Date().toISOString()};db.assets.push(asset);if(!persist()){db.assets.pop();return;}}state.draft.frames[state.frame].assetId=id;if(!state.draft.references.some(x=>x.id===id))state.draft.references.push({id,name:ref.name,url:ref.sourceUrl,borrow:'参考图 · '+ref.author});dirty();closeModal();render();notify('已用于当前画面并保留来源；此图为参考图，请核实使用范围。');}catch{notify('参考图加载失败，请重试；已有创作仍保留。');}return;}

if(a==='view-create'){const [id,n]=v.split('|');const view=discoveryList().find(x=>x.id===id);if(view)begin(window.StudioDiscovery.build(view,Number(n)));return;}
if(a==='structure'){if(saveDraft(true))modal('完整创意结构',structureHTML(state.draft)+B('下载结构图 SVG','structure-svg','','primary space'));return;}
if(a==='structure-svg'){const d=state.draft;const lines=[d.title,d.formula,...d.frames.flatMap((f,n)=>[(n+1)+'. '+f.role,r(f.main),r(f.note),db.assets.some(a=>a.id===f.assetId)?'已选择素材':'素材待补充']),...Object.entries(d.f).map(([k,v])=>(C.labels[k]||k)+'：'+r(Array.isArray(v)?v.map(row=>Array.isArray(row)?row.join(' | '):row).join('\n'):v))].flatMap(t=>String(t||'').split('\n').flatMap(t=>t.match(/.{1,36}/gu)||['']));const svg='<svg xmlns="http://www.w3.org/2000/svg" width="820" height="'+(lines.length*32+60)+'"><rect width="100%" height="100%" fill="#f7f7fa"/>'+lines.map((t,n)=>'<text x="30" y="'+(40+n*32)+'" font-size="18" fill="#23253d">'+E(t)+'</text>').join('')+'</svg>';download(d.title+'-创意结构.svg',svg,'image/svg+xml');notify('已下载当前编辑内容的结构图 SVG。');return;}
if(a==='close'){closeModal();return;}if(a==='blank'){blank();return;}if(a==='platform'){state.platform=v;try{localStorage.setItem('tmb.shared.platform',JSON.stringify(v));}catch{}state.theme=state.angle=state.form=state.q='';state.page=0;db.settings.platform=v;persist();if(state.view==='discover')remember();render();return;}if(a==='theme'){state.theme=v;state.page=0;state.selected=null;remember();render();return;}if(a==='reset'){state.theme=state.angle=state.form=state.q='';state.page=0;state.selected=null;remember();render();return;}if(a==='select'){state.selected=v;remember();render();if(innerWidth<900)document.querySelector('.detail')?.scrollIntoView({block:'start'});return;}if(a==='page'){state.page=Math.max(0,Math.min(Number(v),Math.ceil(catalog().length/12)-1));remember();render();return;}if(a==='create'){const it=ITEMS.find(x=>x.id===v);if(it)begin(it);return;}if(a==='save'){saveDraft();return;}if(a==='back'){if(guard()){go(state.returnHash||'#discover');setTimeout(()=>scrollTo(0,state.scroll),50);}return;}if(a==='frame'){state.frame=Number(v);render();return;}if(a==='addframe'){state.draft.frames.push({role:'新画面',main:'',sub:'',note:'',layout:'',style:'',assetId:null});state.frame=state.draft.frames.length-1;dirty();render();return;}if(a==='removeframe'){if(state.draft.frames.length===1){notify('至少保留一张画面。');return;}if(!confirm('移除当前画面？此操作将在保存草稿后生效。'))return;state.draft.frames.splice(state.frame,1);state.frame=Math.max(0,state.frame-1);dirty();render();return;}if(a==='resources'){showResources(v);return;}if(a==='useasset'){state.draft.frames[state.frame].assetId=v;dirty();closeModal();render();notify('已将真实素材用于当前画面。');return;}if(a==='clearasset'){state.draft.frames[state.frame].assetId=null;dirty();render();return;}if(a==='library'){state.library=v;render();return;}if(a==='browsetheme'){state.theme=v;state.page=0;go(queryHash('discover'));return;}if(a==='bindcase'){const cases=casesList(state.draft.p,state.draft.type).concat(db.cases),c=cases.find(x=>x.id===v);if(!c)return;const n=state.draft.references.findIndex(x=>x.id===v);if(n<0)state.draft.references.push({id:c.id,name:c.name,url:C.safeURL(c.url),borrow:c.borrow});else state.draft.references.splice(n,1);dirty();showResources('cases');notify(n<0?'案例结构已加入当前创作参考。':'已移除此案例参考。');return;}if(a==='bindidea'){const id='idea-'+state.draft.p+'-'+v;if(!state.draft.references.some(x=>x.id===id)){state.draft.references.push({id,name:v,borrow:PB[state.draft.p]?.[v]?.content?.formula||''});dirty();}notify('创意结构已加入参考，没有覆盖现有文案。');return;}if(a==='evidence'){const i=ITEMS.find(x=>x.id===v),p=state.platform,t=state.theme;state.platform=i.p;state.theme=i.type;modal('案例与创意依据',resources('cases'));state.platform=p;state.theme=t;return;}if(a==='preview'){preview();return;}if(a==='txt'){download(state.draft.title+'.txt',publishText(state.draft),'text/plain;charset=utf-8');notify('已下载当前作品的完整文案 TXT。');return;}if(a==='json'){const ids=new Set(state.draft.frames.map(f=>f.assetId));download(state.draft.title+'.json',JSON.stringify({format:'tmb-studio2-draft',version:1,draft:state.draft,assets:db.assets.filter(x=>ids.has(x.id))},null,2),'application/json');notify('已下载可编辑草稿，包含当前使用的本地图片。');return;}if(a==='copy'){try{await navigator.clipboard.writeText(publishText(state.draft));notify('已复制发布文案，不含画面说明；朋友圈使用版本1。');}catch{notify('浏览器不允许复制，请下载文案 TXT。');}return;}if(a==='png'){await png();return;}if(a==='duplicate'){const d=C.clone(db.drafts.find(x=>x.id===v));d.id=C.uid();d.title+=' · 副本';C.upsert(db,d);if(persist()){render();notify('已创建独立副本。');}return;}if(a==='addcase'){modal('录入行业案例',`<form id="case-form" class="fields"><label>案例名称<input name="name" required maxlength="120"></label><label>来源链接<input name="url" type="url" required placeholder="https://"></label><label>平台<select name="p">${Object.entries(names).map(([p,n])=>`<option value="${p}" ${p===(state.draft?.p||state.platform)?'selected':''}>${n}</option>`).join('')}</select></label><label>内容主题<select name="theme">${[...new Set(ITEMS.filter(i=>i.p===state.platform).map(i=>i.type))].map(t=>`<option>${E(t)}</option>`).join('')}</select></label><label>内容摘要<textarea name="what" required></textarea></label><label>可以借鉴什么<textarea name="borrow" required></textarea></label><label>数据依据与采集时间（没有请留空）<textarea name="why"></textarea></label><button class="primary" type="submit">保存到当前浏览器</button></form>`);return;}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){e.preventDefault();Promise.resolve(action(b.dataset.action,b.dataset.value)).catch(err=>{console.error(err);notify('操作未完成，请重试；现有内容仍保留。');});return;}const a=e.target.closest('a');if(a&&!a.target&&(a.getAttribute('href')?.startsWith('#')||a.getAttribute('href')?.startsWith('materials.html'))&&!guard())e.preventDefault();});
document.addEventListener('input',e=>{const el=e.target;if(el.matches('[data-case-search]')){const q=el.value.trim().toLocaleLowerCase(),scope=el.closest('.case-library'),cards=scope.querySelectorAll('[data-case-search-item]');let shown=0;cards.forEach(c=>{const match=!q||c.dataset.caseSearch.toLocaleLowerCase().includes(q);c.hidden=!match;if(match)shown++;});const count=scope.querySelector('[data-case-count]');if(count)count.textContent='显示 '+shown+' 条';scope.querySelector('[data-case-empty]').hidden=shown>0;return;}const d=state.draft;if(state.view!=='edit'||!d)return;if(el.dataset.result){d.results=d.results||{};const k=el.dataset.result;d.results[k]=['period','attribution'].includes(k)?el.value:el.value===''?null:Math.max(0,Number(el.value));}else if(el.dataset.draft){const k=el.dataset.draft;d[k]=k==='textScale'?Number(el.value):el.value;if(k==='storeName')d.vars['店名']=el.value;}else if(el.dataset.frameField)d.frames[state.frame][el.dataset.frameField]=el.value;else if(el.dataset.copy)d.f[el.dataset.copy]=el.value;else if(el.dataset.script)d.f[el.dataset.script][Number(el.dataset.row)][Number(el.dataset.col)]=el.value;else if(el.dataset.var)d.vars[el.dataset.var]=el.value;else return;dirty();updatePreview();});
document.addEventListener('change',e=>{const el=e.target;if(el.hasAttribute('data-export-frame')){exportCount();return;}if(el.id==='asset-file'){upload(el.files[0]);return;}if(el.id==='draft-file'){importDraft(el.files[0]);return;}if(el.dataset.context==='city'){state.storeId=STORES.find(s=>s.vars['城市']===el.value).id;db.settings.storeId=state.storeId;saveSharedStore();persist();render();return;}if(el.dataset.context==='storeId'){state.storeId=el.value;db.settings.storeId=el.value;saveSharedStore();persist();render();return;}if(el.closest('#filter-form')&&el.tagName==='SELECT'){state[el.name]=el.value;state.page=0;remember();render();}if(el.dataset.draft&&['ratio','textPosition'].includes(el.dataset.draft)){state.draft[el.dataset.draft]=el.value;dirty();updatePreview();}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,values=Object.fromEntries(new FormData(f));if(f.id==='filter-form'){state.angle=values.angle||'';state.form=values.form||'';state.q=values.q.trim();state.page=0;remember();render();}if(f.id==='blank-form'){if(restrictedPurchase(values.idea)){notify('这条想法需要改为介绍线下服务内容后再生成。');return;}let item;if(values.mode==='local'){try{item=window.TMB_SERVICE.build({...values,occasion:'常规'},0);}catch{notify('本地结构生成失败，请使用空白草稿。');return;}}else item={p:values.p,type:values.theme,title:values.idea.slice(0,45),angle:values.idea,formula:'自主创意',f:values.p==='xhs'?{title:'',body:'',tags:'',replies:''}:values.p==='pyq'?{v1:'',v2:'',v3:'',pics:'',timing:''}:{post:'',script:[['0–3秒','','']],tags:'',replies:''},frames:[{role:'封面 / 开头',main:values.idea.slice(0,30),sub:'',note:'',layout:'',style:''}]};item.id=null;closeModal();begin(item);}if(f.id==='case-form'){if(restrictedPurchase(JSON.stringify(values))){notify('内容不符合当前规范，案例未保存。');return;}const url=C.safeURL(values.url);if(!url){notify('请填写有效的 http 或 https 来源链接。');return;}const c={...values,url,id:C.uid(),source:'手动录入',type:'行业案例',createdAt:new Date().toISOString()};db.cases.unshift(c);if(!persist()){db.cases.shift();return;}closeModal();if(state.view==='edit')showResources('cases');else render();notify('案例已保存在当前浏览器，尚未云端同步。');}});
document.addEventListener('keydown',e=>{if(!$('#overlay').firstChild)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const nodes=[...$('#overlay').querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled),first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault();}}});
window.addEventListener('beforeunload',e=>{if(state.dirty){e.preventDefault();e.returnValue='';}});
function route(){closeModal();if(!DISCOVERY_ENABLED&&!/^#(?:edit\/|drafts(?:\?|$)|library(?:\?|$))/.test(location.hash)){location.replace('materials.html');return;}const raw=location.hash.slice(1)||'discover',parts=raw.split('?'),q=new URLSearchParams(parts[1]||'');if(parts[0].startsWith('edit/')){const id=parts[0].slice(5),d=db.drafts.find(x=>x.id===id&&!x.deletedAt);state.view='edit';if(state.draft?.id!==id){state.draft=d?C.clone(d):null;state.referenceTheme=d?.p==='xhs'?d.type:'';}state.returnHash=state.draft?.returnHash||'#discover';state.scroll=state.draft?.returnScroll||0;state.frame=0;state.dirty=false;}else{state.view=['discover','drafts','library'].includes(parts[0])?parts[0]:'discover';if(q.has('p')&&PLAT[q.get('p')])state.platform=q.get('p');if(state.view==='discover'){for(const k of ['theme','angle','form','q'])state[k]=q.get(k)||'';state.page=Math.max(0,parseInt(q.get('page'))||0);state.selected=q.get('selected');}if(state.view==='library'&&q.has('tab'))state.library=['ideas','assets','cases','rules'].includes(q.get('tab'))?q.get('tab'):'ideas';}render();}
window.addEventListener('hashchange',()=>{if(state.dirty&&!saveDraft(true)){history.replaceState(null,'','#edit/'+state.draft.id);return;}route();});
window.addEventListener('pageshow',syncSharedStore);window.addEventListener('storage',e=>{if(e.key==='tmb.studio2.legacy.cur')syncSharedStore();});
const params=new URLSearchParams(location.search);if(params.has('template')){let pool=ITEMS;let edits={};let materialStore=null;try{pool=pool.concat(JSON.parse(localStorage.getItem('tmb.studio2.legacy.custom')||'[]'));edits=JSON.parse(localStorage.getItem('tmb.studio2.legacy.edits')||'{}');materialStore=JSON.parse(localStorage.getItem('tmb.studio2.legacy.stores')||'[]').find(s=>s.id===params.get('store'));}catch{}if(params.get('store')&&STORES.some(s=>s.id===params.get('store')))state.storeId=params.get('store');let it=pool.find(i=>i.id===params.get('template'));if(it){it=C.clone(it);for(const [k,v]of Object.entries(edits[it.id]||{})){if(k==='coverMain'){it.cover=it.cover||{};it.cover.main=v;if(it.frames?.[0])it.frames[0].main=v;}else if(k==='coverSub'){it.cover=it.cover||{};it.cover.sub=v;if(it.frames?.[0])it.frames[0].sub=v;}else if(k==='title')it.title=v;else {it.f=it.f||{};it.f[k]=v;}}} if(it){history.replaceState(null,'',location.pathname+'#discover');state.draft=C.createDraft(it,materialStore||store());try{const selected=JSON.parse(localStorage.getItem('tmb.studio2.legacy.templateAssets')||'{}')[(params.get('store')||state.storeId)+':'+it.id]||{};state.draft.frames.forEach((f,n)=>{const a=selected['__frame'+n]||selected[f.slot];if(!a?.data)return;let asset=db.assets.find(x=>x.id==='legacy-'+a.id);if(!asset){asset={...a,id:'legacy-'+a.id,createdAt:new Date().toISOString()};db.assets.push(asset);}f.assetId=asset.id;if(!state.draft.references.some(x=>x.id===asset.id))state.draft.references.push({id:asset.id,name:a.name,url:a.sourceUrl||'',borrow:a.source||'资料库素材'});});}catch{}C.upsert(db,state.draft);if(persist())history.replaceState(null,'','#edit/'+state.draft.id);}}route();if(!sharedStoreId())saveSharedStore();if(loaded.error)notify(loaded.error);
})();
